+package com.example.views;
+
+import java.util.regex.Pattern;
+
+import com.example.views.MessageService.ContactMessage;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+
+    private final MessageService service;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    public ContactView(MessageService service) {
+        this.service = service;
+        RouterLink about = new RouterLink("About", AboutView.class);
+
+        email.setManualValidation(true);
+        send.addClickListener(e -> send());
+        send.addClickShortcut(Key.ENTER);
+        for (var f : new com.vaadin.flow.component.HasValue<?, ?>[] { name, email, phone, message }) {
+            f.addValueChangeListener(e -> send.setEnabled(true));
+        }
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setItems(service.findAll());
+
+        add(new H1("Contact"), about, name, email, phone, message, send, grid);
+    }
+
+    private void send() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+
+        String n = name.getValue();
+        String em = email.getValue().trim();
+        String ph = phone.getValue().trim();
+        String msg = message.getValue();
+        boolean ok = true;
+
+        if (n.isBlank()) {
+            fail(name, "Name is required");
+            ok = false;
+        }
+        if (!em.isEmpty() && !EMAIL.matcher(em).matches()) {
+            fail(email, "Enter a valid e-mail address");
+            ok = false;
+        } else if (em.isEmpty() && ph.isEmpty()) {
+            fail(email, "Give an e-mail address or a phone number");
+            ok = false;
+        }
+        if (msg.isBlank()) {
+            fail(message, "Message is required");
+            ok = false;
+        } else if (msg.length() > 500) {
+            fail(message, "Message must be at most 500 characters");
+            ok = false;
+        }
+        if (!ok) {
+            return;
+        }
+
+        service.add(new ContactMessage(n.trim(), em, ph, msg));
+        grid.setItems(service.findAll());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private static void fail(com.vaadin.flow.component.shared.HasValidationProperties f, String text) {
+        f.setErrorMessage(text);
+        f.setInvalid(true);
+    }
+
+    private boolean dirty() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!dirty()) {
+            return;
+        }
+        var action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard changes?");
+        dialog.add("You have unsent text in the form.");
+        Button keep = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keep, discard);
+        dialog.open();
+    }
+}
