+package com.example.views;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+@Service
+public class MessageService {
+
+    public record ContactMessage(String name, String email, String phone, String message) {
+    }
+
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage m) {
+        messages.add(m);
+    }
+
+    /** Newest first. */
+    public List<ContactMessage> findAll() {
+        List<ContactMessage> copy = new ArrayList<>(messages);
+        Collections.reverse(copy);
+        return copy;
+    }
+}
