+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validateSendAndLeave() {
+        navigate(ContactView.class);
+        test($(Button.class).withText("Send").single()).click();
+        assertEquals("Name is required", $(TextField.class).withCaption("Name").single().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", $(EmailField.class).single().getErrorMessage());
+
+        $(TextField.class).withCaption("Name").single().setValue("A");
+        $(TextField.class).withCaption("Phone").single().setValue("1");
+        $(TextArea.class).single().setValue("hi");
+        test($(Button.class).withText("Send").single()).click();
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        assertTrue($(TextArea.class).single().isEmpty());
+        $(TextField.class).withCaption("Name").single().setValue("B");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+
+        $(TextField.class).withCaption("Name").single().clear();
+        navigate(ContactView.class);
+        $(TextField.class).withCaption("Name").single().setValue("x");
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+        assertEquals(1, $(Dialog.class).all().size());
+        test($(Button.class).withText("Discard").single()).click();
